public void transferBad(Account from, Account to, double amount) {
    synchronized (from.lock) {
        synchronized (to.lock) {
            from.balance -= amount;
            to.balance += amount;
        }
    }
}

// GOOD: Deadlock-Free due to strict lock ordering
// By always acquiring the lock of the account with the smaller ID first, 
// a circular wait is mathematically impossible.
public void transferGood(Account from, Account to, double amount) {
    Account firstLock = from.id < to.id ? from : to;
    Account secondLock = from.id < to.id ? to : from;

    synchronized (firstLock.lock) {
        synchronized (secondLock.lock) {
            from.balance -= amount;
            to.balance += amount;
        }
    }
}

