def update_driver_location(driver_id, lat, lng):
    # Resolution 9 is ~0.1 sq kilometers (perfect for city blocks)
    cell_id = h3.geo_to_h3(lat, lng, resolution=9)

    # In a real system, we'd remove them from their old cell too
    if cell_id not in city_grid:
        city_grid[cell_id] = set()

    city_grid[cell_id].add(driver_id)

def find_nearby_drivers(rider_lat, rider_lng):
    center_cell = h3.geo_to_h3(rider_lat, rider_lng, resolution=9)
    # Get the center cell and its immediate neighbors (1 ring out)
    neighborhood = h3.k_ring(center_cell, 1)

    available_drivers = []
    for cell in neighborhood:
        if cell in city_grid:
            available_drivers.extend(list(city_grid[cell]))
    return available_drivers

public class DispatchGrid {
    // ConcurrentHashMap allows lock-free reads while drivers constantly update GPS
    private final Map<String, ConcurrentLinkedQueue<Driver>> h3Grid = new ConcurrentHashMap<>();

    public void processDriverPing(Driver driver) {
        h3Grid.computeIfAbsent(driver.getH3Index(), k -> new ConcurrentLinkedQueue<>())
              .add(driver);

        // Asynchronously flush historical data to Cassandra to avoid blocking the main thread
        CompletableFuture.runAsync(() -> cassandraRepo.saveHistorical(driver));
    }
}

